# The documentation an install carries, generated by the binary itself: a man
# page per name and per verb, and completions for every shell, under the
# share/ that `chore cli:install` stages beside bin/. And every name answers
# --version and --help as this crate.
source "$(dirname "$0")/lib.sh"

version="$(sed -n 's/^version *= *"\(.*\)"/\1/p' "$REPO/Cargo.toml" | head -n 1)"
share="$SANDBOX/share"
rust-fs-fat generate man "$share" >/dev/null
check "generate man exits 0" test $? -eq 0
rust-fs-fat generate completions "$share" >/dev/null
check "generate completions exits 0" test $? -eq 0

names="$(rust-fs-fat generate names)"
check "generate names lists fs.fat and nothing dosfstools installs" test "$(echo $names)" = "fs.fat"
for name in rust-fs-fat $names; do
    check "$name answers --version as $CRATE $version" \
        test "$("$name" --version)" = "$name ($CRATE) $version"
    "$name" --help >"$SANDBOX/help" 2>&1
    check "$name --help exits 0" test $? -eq 0
    check "$name --help says it is read-only" grep -qi 'read-only' "$SANDBOX/help"
    check "$name has bash completions" test -s "$share/bash-completion/completions/$name"
    check "$name has zsh completions" test -s "$share/zsh/site-functions/_$name"
    check "$name has fish completions" test -s "$share/fish/vendor_completions.d/$name.fish"
done
check "fs.fat has its man page" test -s "$share/man/man1/fs.fat.1"
for verb in info ls stat cat export scan chain fat; do
    check "fs.fat $verb has its man page" test -s "$share/man/man1/fs.fat-$verb.1"
done
# The names dosfstools owns are never ours.
for taken in mkfs.fat fsck.fat mkfs.vfat fsck.vfat mkfs.msdos fsck.msdos fatlabel dosfslabel; do
    check "$taken is not one of our names" test "$(echo "$names" | grep -c -x "$taken")" -eq 0
done

finish
